<style>.ch_avatar_modal{padding:18px!important}.ch_avatar_head{display:flex;align-items:center;gap:12px;margin:4px 0 18px;padding:8px 34px 8px 2px}.ch_avatar_icon{width:44px;height:44px;border-radius:14px;display:flex;align-items:center;justify-content:center;color:#fff;font-size:22px;background:linear-gradient(135deg,#6366f1,#ec4899 60%,#06b6d4);box-shadow:0 5px 20px #6366f144}.ch_avatar_title{font-size:19px;font-weight:800}.ch_avatar_sub{font-size:12px;opacity:.72;margin-top:3px}.ch_avatar_grid{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:10px;max-height:55vh;overflow-y:auto;overflow-x:hidden;padding:2px 4px 8px}.ch_avatar_choice{position:relative;min-width:0;border:1px solid rgba(127,127,127,.22);border-radius:13px;background:rgba(127,127,127,.06);padding:8px 4px 7px;color:inherit;cursor:pointer;transition:transform .16s,border-color .16s,background .16s;overflow:hidden}.ch_avatar_choice:hover{transform:translateY(-2px);border-color:#818cf8;background:rgba(99,102,241,.10)}.ch_avatar_choice.selected{border:2px solid #6366f1;padding:7px 3px 6px;background:rgba(99,102,241,.13);box-shadow:0 0 0 2px rgba(99,102,241,.12)}.ch_avatar_image{display:block;width:min(100%,76px);aspect-ratio:1;margin:0 auto 6px;border-radius:50%;overflow:hidden;background:#101326;box-shadow:0 0 0 2px rgba(99,102,241,.55),0 0 14px rgba(99,102,241,.22)}.ch_avatar_image img{display:block;width:100%;height:100%;object-fit:cover;border-radius:50%}.ch_avatar_label{display:block;font-size:10px;line-height:1.25;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;opacity:.85}.ch_avatar_check{display:none;position:absolute;right:4px;top:4px;width:19px;height:19px;border-radius:50%;background:#6366f1;color:#fff;font-size:10px;align-items:center;justify-content:center}.ch_avatar_choice.selected .ch_avatar_check{display:flex}.ch_avatar_choice.loading{opacity:.55;pointer-events:none}.ch_avatar_hint{font-size:12px;opacity:.75;padding:12px 2px 0}.ch_avatar_hint i{color:#06b6d4;margin-